from z3 import *

# We need to find a graph with 24 vertices, girth >= 7, and degree between 3 and 4
# Let's use z3 to solve this

n = 24

# Create boolean variables for each possible edge
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f'e_{i}_{j}')

solver = Solver()

# Constraint: each vertex has degree between 3 and 4
for v in range(n):
    edge_vars = []
    for u in range(v):
        edge_vars.append(edges[(u,v)])
    for w in range(v+1, n):
        edge_vars.append(edges[(v,w)])

    degree = Sum([If(e, 1, 0) for e in edge_vars])
    solver.add(degree >= 3)
    solver.add(degree <= 4)

# Constraint: no cycles of length 3, 4, 5, or 6
# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

# No cycles of length 4
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # Check all possible 4-cycles among these 4 vertices
                # A 4-cycle uses exactly 4 edges forming a cycle
                # Possible 4-cycles: (i,j,k,l), (i,j,l,k), (i,k,j,l)
                solver.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(k,l)], edges[(i,l)])))
                solver.add(Not(And(edges[(i,j)], edges[(j,l)], edges[(k,l)], edges[(i,k)])))
                solver.add(Not(And(edges[(i,k)], edges[(j,k)], edges[(j,l)], edges[(i,l)])))

print("Constraints added, solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    edge_list = []
    for (i,j), var in edges.items():
        if m.evaluate(var) == True:
            edge_list.append((i,j))
    print(f"Number of edges: {len(edge_list)}")
    print("Edges:", edge_list)
else:
    print("UNSATISFIABLE")
